# room.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$defs": {
    "group": {
      "additionalProperties": false,
      "properties": {
        "active": {
          "type": "boolean"
        },
        "authorized_by": {
          "minLength": 1,
          "type": "string"
        },
        "group_id": {
          "pattern": "^group-[a-z0-9][a-z0-9-]*$",
          "type": "string"
        },
        "members": {
          "items": {
            "minLength": 1,
            "type": "string"
          },
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "purpose": {
          "enum": [
            "owner",
            "delivery",
            "review",
            "observers",
            "assigned-work"
          ],
          "type": "string"
        },
        "tag_selector": {
          "items": {
            "pattern": "^[a-z][a-z0-9._:-]{0,63}$",
            "type": "string"
          },
          "type": "array",
          "uniqueItems": true
        }
      },
      "required": [
        "group_id",
        "purpose",
        "members",
        "authorized_by",
        "active"
      ],
      "type": "object"
    }
  },
  "$id": "https://coding-hermes.local/chd32/schemas/room.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "description": "A permissioned work space with flexible authorized groups and descriptive tags; tags never grant authority.",
  "examples": [
    {
      "commit_seq": 8,
      "head_seq": 12,
      "kind": "task",
      "member_ids": [
        "mgr-1",
        "sup-1"
      ],
      "owner": "mgr-1",
      "record_id": "room:task-wf01",
      "rev": 1,
      "room_id": "task-wf01",
      "schema_version": 3,
      "state": "open",
      "thread_policy": "replies-by-root",
      "written_by": "controller-1"
    }
  ],
  "properties": {
    "closed_at": {
      "format": "date-time",
      "type": [
        "string",
        "null"
      ]
    },
    "commit_seq": {
      "minimum": 1,
      "type": "integer"
    },
    "created_at": {
      "format": "date-time",
      "type": "string"
    },
    "groups": {
      "items": {
        "$ref": "#/$defs/group"
      },
      "type": "array"
    },
    "head_seq": {
      "minimum": 0,
      "type": "integer"
    },
    "kind": {
      "enum": [
        "objective",
        "task",
        "space"
      ],
      "type": "string"
    },
    "member_ids": {
      "items": {
        "type": "string"
      },
      "type": "array",
      "uniqueItems": true
    },
    "membership_revision": {
      "minimum": 1,
      "type": "integer"
    },
    "owner": {
      "minLength": 1,
      "type": "string"
    },
    "parent_room_id": {
      "type": [
        "string",
        "null"
      ]
    },
    "record_id": {
      "minLength": 1,
      "type": "string"
    },
    "rev": {
      "minimum": 1,
      "type": "integer"
    },
    "room_id": {
      "pattern": "^(obj|task|space)-[a-z0-9-]+$",
      "type": "string"
    },
    "schema_version": {
      "minimum": 1,
      "type": "integer"
    },
    "state": {
      "enum": [
        "open",
        "closed",
        "archived"
      ],
      "type": "string"
    },
    "tags": {
      "items": {
        "pattern": "^[a-z][a-z0-9._:-]{0,63}$",
        "type": "string"
      },
      "type": "array",
      "uniqueItems": true
    },
    "thread_policy": {
      "minLength": 1,
      "type": "string"
    },
    "title": {
      "maxLength": 256,
      "minLength": 1,
      "type": "string"
    },
    "written_by": {
      "minLength": 1,
      "type": "string"
    }
  },
  "required": [
    "schema_version",
    "record_id",
    "rev",
    "commit_seq",
    "written_by",
    "room_id",
    "kind",
    "owner",
    "title",
    "parent_room_id",
    "groups",
    "tags",
    "membership_revision",
    "created_at",
    "member_ids",
    "head_seq",
    "thread_policy",
    "state"
  ],
  "title": "CHD RoomRecord",
  "type": "object"
